"""Compact, authored main lessons. Full original chapters remain optional reference."""
from html import escape


def table(headers, rows):
    return '<div class="vl-table"><table><thead><tr>' + ''.join('<th scope="col">'+c+'</th>' for c in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def code(source):
    return '<div class="code"><div class="code-head">Run in Colab · predict the result first</div><pre><code>'+escape(source)+'</code></pre></div>'


def figure(title, rows, columns=None):
    return '<figure class="vl-figure"' + (f' style="--trace-columns:{columns}"' if columns else '') + '><figcaption>'+title+'</figcaption>'+''.join('<div class="vl-trace"><b>'+label+'</b><div class="vl-cards" style="--row-columns:'+str(len(values))+'">'+''.join('<span>'+v+'</span>' for v in values)+'</div></div>' for label,values in rows)+'</figure>'


def flow(title, items):
    return '<figure class="vl-figure"><figcaption>'+title+'</figcaption><ol class="vl-flow">'+''.join('<li>'+v+'</li>' for v in items)+'</ol></figure>'


def equation(label, expression, note=''):
    return '<div class="vl-equation"><span>'+label+'</span><strong>'+expression+'</strong>'+('<p>'+note+'</p>' if note else '')+'</div>'


def section(title, content):
    return '<section class="vl-lesson"><h2>'+title+'</h2>'+content+'</section>'


def task(title, prompt, answer):
    return '<article class="vl-task"><h3>'+title+'</h3><p>'+prompt+'</p><details class="solution"><summary>Check your reasoning</summary><div><p>'+answer+'</p></div></details></article>'


# Content is HTML; code() escapes Python snippets independently.
LESSONS = {
2: [
('Turn text into a calculation', flow('A receipt: input → number → calculation → output', ['<code>"4.10"</code><small>text from input()</small>', '<code>4.1</code><small>float(...)</small>', '<code>4.1 × 3</code><small>total = 12.3</small>', '<code>12.30</code><small>format to 2 decimals</small>']) + code('price = float(input("Price: "))\nquantity = int(input("Quantity: "))\ntotal = price * quantity\nprint(f"Total: {total:.2f}")') + '<p>Enter <code>4.10</code> and <code>3</code>. <code>input()</code> returns text; convert it before doing arithmetic. <code>int</code> stores whole numbers, <code>float</code> decimal approximations, <code>str</code> text and <code>bool</code> True/False. Formatting changes the display, not the stored value.</p>'),
('A name keeps its latest value', code('a = 4\nb = 9\ntemp = a\na = b\nb = temp\nprint(a, b)') + table(['After line','a','b','temp'], [['Start','4','9','—'],['temp = a','4','9','4'],['a = b','9','9','4'],['b = temp','9','4','4']]) + '<p><code>=</code> assigns the value on its right to the name on its left. It is not an algebraic equation. Python runs these lines in order.</p>'),
('Read the operation, then the type', table(['Expression','Result','Meaning'], [['10 / 4','2.5','division'],['10 // 4','2','floor division'],['10 % 4','2','remainder'],['2 ** 3','8','power'],['"10" * 3','"101010"','repeat text'],['int("10") * 3','30','multiply numbers'],['len("cat")','3','count characters'],['"Cat".lower()','"cat"','make lowercase']]) + equation('For integer a and nonzero integer b','a = (a // b) × b + (a % b)') + '<p>Use parentheses to make order clear: <code>(2 + 3) * 4</code> gives 20. A comment starts with <code>#</code>; it explains a choice without running an instruction.</p>'),
('Fix the cause, not the message', table(['Error','Example','Repair'], [['NameError','<code>print(totl)</code>','Use the name you assigned: total.'],['TypeError','<code>"3" + 2</code>','Convert text to a number, or make both values text.'],['ValueError','<code>int("three")</code>','Supply valid digits.']]) + '<p>Read the last line of the error, then inspect the named line. To count work this week, count assignments or arithmetic operations explicitly; one printed line can contain several operations.</p>')],
3: [
('Follow one decision at a time', code('x = 7\nif x % 2 == 0:\n    print("even")\nelse:\n    print("odd")') + flow('Trace x = 7', ['7 % 2 = 1','1 == 0 → False','take else','print odd']) + '<p><code>==</code> compares values. <code>if / elif / else</code> chooses the first matching branch. Indentation shows which instructions belong to it.</p>'),
('A loop is a repeated trace', code('total = 0\nfor i in range(1, 5):\n    total += i\nprint(total)') + figure('range(1, 5): include 1, stop before 5', [('i',['1','2','3','4']),('total after adding i',['1','3','6','10'])]) + '<p><code>total += i</code> means <code>total = total + i</code>. <code>range(n)</code> gives 0 through n − 1. <code>break</code> leaves a loop; <code>continue</code> skips to its next turn.</p>'),
('Two loops: add or multiply?', figure('Each cell is one inner-loop action', [('i = 0',['(0, 0)','(0, 1)','(0, 2)']),('i = 1',['(1, 0)','(1, 1)','(1, 2)']),('i = 2',['(2, 0)','(2, 1)','(2, 2)'])]) + code('n = 3\nfor i in range(n):\n    for j in range(n):\n        print(i, j)') + equation('Nested loops','n × n = n² actions') + '<p>Two separate loops of n turns do n + n = 2n actions. Nesting makes every outer turn repeat the whole inner loop.</p>'),
('Halve until the stopping condition fails', code('n = 20\nsteps = 0\nwhile n > 1:\n    n //= 2\n    steps += 1\nprint(steps)') + figure('Four updates, then n > 1 becomes false', [('n',['20','10','5','2','1'])]) + equation('For a positive integer starting value n','steps = ⌊log₂ n⌋','For powers of two: 2ᵏ → … → 1 takes exactly k updates.') + '<p>A <code>while</code> loop must move toward a stopping condition. Using <code>n += 1</code> here would never reach it.</p>')],
4: [
('A list gives every value a position', figure('Indices start at zero; negative indices count from the end', [('index',['0','1','2','3','4']),('values',['12','7','30','4','18'])]) + code('values = [12, 7, 30, 4, 18]\nprint(values[0], values[-1])  # 12 18\nprint(values[1:4])           # [7, 30, 4]') + '<p>A slice includes its start and excludes its stop. <code>append(x)</code> adds at the end; <code>pop()</code> removes and returns the last value. Access outside the list raises <code>IndexError</code>.</p>'),
('One pass can collect several results', code('total = 0\nlargest = values[0]  # requires a nonempty list\nfor x in values:\n    total += x\n    if x > largest:\n        largest = x\nprint(total, total / len(values), largest)') + figure('Track state after each item', [('x',['12','7','30','4','18']),('total',['12','19','49','53','71']),('largest',['12','12','30','30','30'])]) + equation('One pass through n items','n visits → sum 71, mean 14.2, maximum 30') + '<p>For an empty list, sum is 0; a mean or maximum needs a separate rule. Do not initialise the maximum to 0: that fails for an all-negative list.</p>'),
('A search may inspect every item', figure('Search for 8: compare left to right; no match', [('list',['12 ≠ 8','7 ≠ 8','30 ≠ 8','4 ≠ 8','18 ≠ 8'])]) + equation('q unsuccessful searches in a list of n values','q × n comparisons') + '<p><code>x in values</code> hides a search. A comprehension such as <code>[x for x in values if x % 2 == 0]</code> also visits every item. Short code need not mean little work.</p>'),
('Two names can share one list', code('a = [2, 4]\nb = a\nc = a.copy()\nb.append(6)\nprint(a, b, c)') + flow('References after append', ['<code>a, b</code><small>both point to [2, 4, 6]</small>','<code>c</code><small>points to separate [2, 4]</small>']) + '<p>Assignment does not copy a list. <code>copy()</code> makes a new outer list; nested objects are still shared. Test empty, one-item, repeated and all-negative inputs before measuring speed.</p>')],
5: [
('Give a repeated method a name', code('def contains(values, target):\n    for x in values:\n        if x == target:\n            return True\n    return False\n\nprint(contains([4, 7, 9], 7))') + flow('Function call', ['inputs: [4, 7, 9], 7','check 4 → check 7','return True; stop']) + '<p>A parameter names an input. <code>return</code> sends a result back and ends the call; <code>print</code> only displays it. The final <code>return False</code> belongs after the loop, so all candidates get a chance.</p>'),
('Time only the work you are comparing', flow('Benchmark boundary', ['build data<small>outside timer</small>','start = perf_counter()','call the method','elapsed = perf_counter() − start']) + code('from time import perf_counter\nvalues = list(range(100_000))\nstart = perf_counter()\nfound = contains(values, -1)\nelapsed = perf_counter() - start\nprint(found, elapsed)') + '<p>The missing target forces a full scan. Compare methods on the same data and target. Keep printing and data creation outside the timed region unless those are part of the question.</p>'),
('Repeat before trusting a number', '<p>Illustrative timings for five runs:</p>' + table(['Run','1','2','3','4','5'], [['Time (ms)','4.0','4.1','7.2','4.0','4.2']]) + equation('Same method, five trials','minimum = 4.0 ms; mean = 4.7 ms') + '<p>The minimum can approximate an uninterrupted run; the mean includes interruptions. Report which you use. Warm up once, then repeat; background work and timer resolution can overwhelm tiny measurements.</p>' + code('from timeit import repeat\nsamples = repeat(lambda: contains(values, -1),\n                 number=100, repeat=5)\nseconds_per_call = min(samples) / 100\nprint(seconds_per_call)')),
('Keep evidence separate from a claim', table(['Record','Example'], [['Input family','n distinct integers; target absent'],['Correctness check','returns False'],['Work model','n equality checks'],['Measurement','seconds per call, repetitions and machine'],['Limit','Does not describe early matches']]) + '<p>A faster run is evidence about this experiment. It does not prove that a method is faster for every input or every machine.</p>')],
6: [
('Double n; compare the work', table(['n','n steps','n² steps','2ⁿ steps'], [['4','4','16','16'],['8','8','64','256'],['16','16','256','65,536']]) + equation('Doubling ratio','R(n) = T(2n) / T(n)') + '<p>For linear work the ratio is 2; for quadratic work it is 4. Exponential work has no fixed doubling ratio: 2²ⁿ / 2ⁿ = 2ⁿ.</p>'),
('A ratio gives a candidate power', flow('When T(n) ≈ c nᵖ', ['T(2n) ≈ c (2n)ᵖ','R ≈ 2ᵖ','p ≈ log₂ R']) + table(['Observed ratio','Candidate model'], [['1','constant work'],['2','linear work'],['4','quadratic work'],['8','cubic work']]) + '<p>On a log–log plot, log T = log c + p log n: a power law becomes a straight line with slope p. Both axes use logs. A straight line on ordinary axes means something different.</p>'),
('Not every curve is a pure power', equation('For T(n) = n log₂ n, n > 1','R(n) = 2 + 2 / log₂ n') + table(['n','16','256','65,536'], [['R(n)','2.50','2.25','2.125']]) + '<p>A ratio slowly approaching 2 can belong to n log n, not just n. Small inputs can hide the growing term: for T(n) = 1000 + n, R(n) is near 1 when n is small.</p>'),
('Use a series, not one pair', flow('A useful experiment', ['choose one input family','n, 2n, 4n, 8n','repeat each measurement','plot + compute ratios','compare with counted work']) + '<p>Keep units consistent and timings above the noise floor. A single ratio can be distorted by interruptions, caching or memory pressure. Report a candidate growth model and the input range supporting it; establish the model by counting work.</p>')],
7: [
('Choose one operation to count', code('n = 5\ncount = 0\nfor i in range(n):\n    for j in range(i):\n        count += 1\nprint(count)') + figure('n = 5: only pairs with j < i are visited', [('i = 0',['no pairs']),('i = 1',['(1,0)']),('i = 2',['(2,0)','(2,1)']),('i = 3',['(3,0)','(3,1)','(3,2)']),('i = 4',['(4,0)','(4,1)','(4,2)','(4,3)'])], columns=4) + equation('Count the inner-body executions','T(n) = 0 + 1 + … + (n − 1) = n(n − 1)/2') + '<p>At n = 5, T = 10. The counter counts the chosen action, not every machine instruction.</p>'),
('Combine blocks before simplifying', table(['Structure','Exact count of body actions','Growth'], [['Two separate n-turn loops','n + n = 2n','linear'],['An n-turn loop inside another','n × n = n²','quadratic'],['The triangular loop above','(n² − n)/2','quadratic'],['Repeatedly halve a positive integer','⌊log₂ n⌋','logarithmic']]) + '<p>Read bounds carefully. An inner loop of fixed length 10 gives 10n actions, not n².</p>'),
('Keep exact counts for small inputs', equation('Example count','T(n) = 3n² + 5n + 2 ≈ 3n² for large n') + table(['n','3n²','5n + 2'], [['1','3','7'],['10','300','52'],['100','30,000','502']]) + equation('Which is smaller: 100n or n²?','100n = n² at n = 100, for n > 0') + '<p>Below 100, n² is smaller; above 100, 100n is smaller. Growth classes describe the long run and do not settle every small-input comparison.</p>'),
('State what one step means', '<p>Our simple model treats a fixed-size number comparison, array access or arithmetic operation as one step. This makes the count independent of processor speed.</p>' + table(['Safe classroom assumption','When it needs refinement'], [['Compare small integers in one step','Very large integers need work proportional to their length.'],['Read one list position in one step','Searching for a value may read many positions.'],['One call is one line of code','The function may contain a loop or a sort.']]) + '<p>State the input size, the counted operation and the assumptions alongside T(n).</p>')],
8: [
('Big-O is an upper bound', equation('A concrete bound, for n ≥ 1','3n + 2 ≤ 5n ⇒ 3n + 2 is O(n)') + figure('At each n, the bound stays above the count', [('n',['1','2','4','8']),('3n + 2',['5','8','14','26']),('5n',['5','10','20','40'])]) + '<p>T(n) is O(g(n)) when some constants c > 0 and n₀ make T(n) ≤ c g(n) for every n ≥ n₀. Here c = 5 and n₀ = 1. Big-O does not mean an exact time.</p>'),
('Use a tight description when you can', table(['Notation','What it promises','Example'], [['O(g)','eventual upper bound','3n + 2 is O(n), also O(n²)'],['Ω(g)','eventual lower bound','3n + 2 is Ω(n)'],['Θ(g)','both bounds, same growth','3n + 2 is Θ(n)']]) + flow('Common growth classes, increasing eventually', ['1','log n','n','n log n','n²','2ⁿ']) + '<p>Keep the fastest-growing term; constant factors do not change Θ. Changing the base of a logarithm changes only a constant factor.</p>'),
('Name the case before the bound', table(['Linear search, n > 0','Equality checks'], [['Best: first item matches','1'],['Worst: absent or last','n'],['Average: target present, each position equally likely','(n + 1)/2']]) + equation('Average under that stated assumption','(1 + 2 + … + n)/n = (n + 1)/2') + '<p>Big-O itself does not mean “worst case”. You can bound the best, average or worst-case count. An average needs a model of which inputs occur.</p>'),
('Count memory separately', code('def doubled(values):\n    return [2 * x for x in values]') + equation('n values, fixed-size arithmetic','Θ(n) time; Θ(n) result storage') + '<p>This function creates n new entries. A loop that only keeps a running sum uses Θ(1) extra storage under the fixed-size-number model. State whether output storage is included.</p>')],
9: [
('Anagrams have equal letter counts', figure('listen and silent: order changes, counts do not', [('letter',['e','i','l','n','s','t']),('listen',['1','1','1','1','1','1']),('silent',['1','1','1','1','1','1'])]) + '<p>First define the rules: here inputs contain only lowercase English letters, and every character counts. Repeated letters matter: <code>aab</code> and <code>abb</code> are not anagrams.</p>'),
('Four methods, one decision', table(['Method','Work for length n','Main idea'], [['Cross off a matching letter','O(n²)','Search remaining positions for each letter.'],['Sort both strings','O(n log n)','Equal sorted sequences have equal counts.'],['Try every permutation','O(n · n!)','Generate candidates and compare each.'],['Count k possible letters','O(n + k)','Compare the two frequency arrays.']]) + '<p>These are upper bounds. The permutation bound includes up to n work per candidate. Early mismatches can finish sooner. With a fixed alphabet k = 26, counting is linear.</p>'),
('Build a count, then cancel it', code('def anagram(a, b):\n    if len(a) != len(b):\n        return False\n    counts = [0] * 26\n    for ch in a:\n        counts[ord(ch) - ord("a")] += 1\n    for ch in b:\n        counts[ord(ch) - ord("a")] -= 1\n    return all(c == 0 for c in counts)') + figure('Trace aab against abb; show only a and b', [('counts for aab',['a: 2','b: 1']),('subtract abb',['a: 1','b: −1'])]) + '<p>The final nonzero entries show the mismatch. This implementation requires a–z input; validate or normalise first if the input rules differ.</p>'),
('Compare on the same job', equation('Frequency-array work','n increments + n decrements + k checks') + '<p>Test empty strings, repeated letters, unequal lengths, a valid pair and a same-length non-pair. Time each method on the same families. For general text, a dictionary counter can handle a larger alphabet; its lookup cost is average-case, and case/spacing rules must be explicit.</p>')],
10: [
('Removing the front shifts the rest', figure('pop(0) on [A, B, C, D]', [('before',['A','B','C','D']),('after',['B ←','C ←','D ←'])], columns=4) + equation('Remove every item from the front','(n − 1) + (n − 2) + … + 1 = n(n − 1)/2 shifts') + '<p>A Python list stores references in an array. Access by index is O(1). Removing its last item avoids shifting the others; repeatedly removing the first creates quadratic work.</p>'),
('An occasional expensive append can average out', figure('A simplified capacity-doubling model, not exact Python capacities', [('capacity',['1','2','4','8','16']),('copy on growth',['—','1','2','4','8'])]) + equation('Over n appends, geometric copying stays linear','1 + 2 + 4 + … &lt; 2n') + '<p>Most appends place one reference; a resize copies many. Spread all resizing work over the whole sequence: append costs O(1) amortised. An individual append can still take O(n). Python uses its own overallocation rule.</p>'),
('Choose the operation before the container', table(['Operation','list','collections.deque'], [['Read a middle index','O(1)','O(n)'],['Append at an end','O(1) amortised','O(1)'],['Remove from the front','O(n)','O(1)'],['Search for a value','O(n)','O(n)']]) + code('from collections import deque\nqueue = deque(["A", "B", "C"])\nqueue.append("D")\nfirst = queue.popleft()\nprint(first, list(queue))') + '<p>A deque fits a queue: add at the back, remove at the front. It does not make arbitrary searches constant-time.</p>'),
('Repeated copying can hide inside short code', code('parts = ["algorithm", "analysis", "with", "Python"]\ntext = " ".join(parts)\nprint(text)') + equation('Naïve repeated prefix copying, n equal-size pieces','1 + 2 + … + n = n(n + 1)/2 units') + '<p><code>join</code> builds the final text in work proportional to total output length. Some Python string-concatenation patterns are optimised, so timings may vary; use the copying model only when each step really copies the prefix. Repeated list <code>result = result + [x]</code> does copy the growing list.</p>')],
11: [
('Select the information you need to keep', table(['Need','Container','Example'], [['Order and repeated values','list','["red", "blue", "red"]'],['Distinct values, membership','set','{"red", "blue"}'],['A value associated with each key','dict','{"red": 2, "blue": 1}']]) + '<p>A set removes multiplicity and has no positional indexing. Dictionaries preserve insertion order; assigning an existing key replaces its value.</p>'),
('A hash narrows the search', figure('Toy bucket rule: integer key % 8; real Python differs', [('key',['16','24','40','19']),('bucket',['0','0','0','3']),('contents',['0: 16, 24, 40','3: 19'])]) + '<p>Several keys may choose the same bucket: a collision. The table must still distinguish them by equality. Hashing is not the same as sorting, and a collision does not make different keys equal.</p>' + equation('Under normal hashing assumptions','membership: O(1) average; O(n) worst case') + '<p>These bounds assume bounded-cost hashing and comparison. Hashing a long fresh string also depends on its length. Keys must be hashable; a mutable list cannot be a key.</p>'),
('Count words in one pass', code('words = "red blue red green blue red".split()\ncounts = {}\nfor word in words:\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)') + figure('Dictionary values after the full pass', [('key',['red','blue','green']),('count',['3','2','1'])]) + '<p><code>get(word, 0)</code> returns 0 when the key is missing. <code>collections.Counter(words)</code> provides the same counting idea. Punctuation and case need a stated normalisation rule for real text.</p>'),
('Pay once, then reuse', equation('q membership queries in n values','list: O(qn) worst case · build set once: O(n + q) average') + code('values = [2, 4, 7, 9]\nqueries = [4, 8]\nallowed = set(values)\nfor query in queries:\n    print(query in allowed)') + '<p>Building a new set inside every query repeats the setup cost. A set uses extra memory and loses duplicates; choose it only when those changes preserve the required result.</p>')],
12: [
('Sorted order makes discarding safe', figure('Find 33 in a sorted list, using inclusive bounds', [('index',['0','1','2','3','4','5','6','7']),('value',['3','7','9','14','21','28','33','40']),('check 1',['mid 3: 14 &lt; 33','keep indices 4…7']),('check 2',['mid 5: 28 &lt; 33','keep indices 6…7']),('check 3',['mid 6: 33','found'])]) + '<p>Each failed comparison removes the middle item and one side. Without sorted order, the discarded side might contain the target.</p>'),
('Make the interval shrink every time', code('def binary_search(a, target):\n    low, high = 0, len(a) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if a[mid] == target:\n            return mid\n        if a[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1') + equation('Worst-case middle checks, n > 0','⌊log₂ n⌋ + 1') + '<p>Empty input makes high = −1, so the loop never runs. With duplicates, this version returns a matching index, not necessarily the first. The +1 and −1 prevent checking the same middle forever.</p>'),
('Include the price of preparing the data', table(['q queries on initially unsorted n values','Total work model'], [['Scan each time','O(qn)'],['Sort once, then binary search','O(n log n + q log n)'],['Build a set once, membership only','O(n + q) average']]) + '<p>For one query, sorting may cost more than scanning. A set is suitable for membership; sorted order also supports ranges. Constants and required outputs decide which model fits.</p>'),
('Test boundaries; use insertion positions for ranges', code('from bisect import bisect_left, bisect_right\na = [2, 4, 4, 7, 9]\ncount = bisect_right(a, 7) - bisect_left(a, 4)\nprint(count)  # 3 values in the inclusive range [4, 7]') + figure('Boundary test set', [('test',['empty','one hit','one miss']),('test',['first hit','last hit','interior gap'])]) + '<p><code>bisect_left</code> finds the first allowed position; <code>bisect_right</code> goes after equal values. Finding a position is logarithmic; inserting into a list can still shift n items.</p>')],
13: [
('Watch neighbouring swaps move the maximum', figure('Bubble sort: shorten the unsorted part after each pass', [('start',['5','1','4','2','8']),('pass 1',['1','4','2','5','8']),('pass 2',['1','2','4','5','8']),('pass 3',['1','2','4','5','8'])]) + table(['Pass','Comparisons','Swaps'], [['1','4','3'],['2','3','1'],['3','2','0 → stop']]) + '<p>This version stops after a pass with no swaps: 9 comparisons and 4 swaps here. A different stopping rule can change the count.</p>'),
('Different methods exploit different structure', table(['Method','Best time','Worst time','What moves'], [['Bubble, with early stop','Θ(n)','Θ(n²)','Adjacent out-of-order pairs'],['Selection','Θ(n²)','Θ(n²)','Choose the smallest remaining item'],['Insertion','Θ(n)','Θ(n²)','Insert into a sorted prefix']]) + equation('Selection comparisons, regardless of initial order','(n − 1) + … + 1 = n(n − 1)/2') + '<p>Insertion sort does little work on nearly sorted input. In its usual shifting version, every shift removes one inversion: a pair whose order is wrong.</p>'),
('Merge: divide the list, then combine sorted halves', figure('Merge sort example', [('split',['[5, 1]','[4, 2]']),('sort halves',['[1, 5]','[2, 4]']),('merge',['1','2','4','5'])]) + equation('For n = 2ᵏ: k merge levels, linear work per level','T(n) = Θ(n log₂ n)') + '<p>Merging repeatedly takes the smaller front item. A typical array implementation uses O(n) extra storage. Unequal halves for other n do not change the growth class.</p>'),
('Use keys; preserve ties when needed', code('students = [("Ada", 80), ("Lin", 70), ("Sam", 80)]\nranked = sorted(students, key=lambda pair: pair[1])\nprint(ranked)') + figure('Stable score sort: Ada stays before Sam', [('result',['Lin: 70','Ada: 80','Sam: 80'])]) + '<p><code>sorted</code> returns a new list. <code>list.sort()</code> changes that list and returns <code>None</code>. <code>lambda pair: pair[1]</code> selects the second field (the score). Python sorting is stable: equal keys keep their original order. Its adaptive sort has O(n log n) worst-case time and can exploit existing order.</p>')],
14: [
('Improve a method without changing its answer', flow('One complete analysis', ['specify the result','test edge cases','count expensive work','choose a better structure','compare results','measure and explain']) + '<p>Example: decide whether two different positions contain values that sum to a target. Returning the same Boolean result is required before comparing speed.</p>'),
('Replace repeated searches with remembered values', code('def two_sum(values, target):\n    seen = set()\n    for x in values:\n        if target - x in seen:\n            return True\n        seen.add(x)\n    return False') + figure('Trace [4, 1, 6, 3], target = 7', [('x',['4','1','6']),('need',['3','6','1']),('seen before check',['set()','{4}','{4, 1}']),('result',['continue','continue','True; stop'])]) + '<p>Check before adding x: otherwise a single 4 could incorrectly match itself for target 8. Two separate 4s may form a valid pair.</p>'),
('Write the time–memory tradeoff', table(['Method','No-pair input of length n','Extra memory'], [['Test every pair i &lt; j','n(n − 1)/2 pair tests; Θ(n²)','Θ(1)'],['Remember previous values','n set lookups; O(n) average total','O(n) worst case']]) + '<p>The set method assumes bounded-cost arithmetic and ordinary hashing. Adverse collisions can make total time quadratic. Test empty input, one item, duplicate values, negative values and no valid pair.</p>'),
('Make the final evidence small and reproducible', table(['Report item','What to show'], [['Correctness','Same outputs on a stated test set'],['Model','Input size, counted operation, time and memory bounds'],['Experiment','Input families, repeated timings and units'],['Interpretation','Why growth matches or differs from the count'],['Limit','What the evidence does not establish']]) + '<p>Use a profiler to locate expensive calls before rewriting code. <em>tottime</em> excludes called functions; <em>cumtime</em> includes them. Profiling adds overhead, so use separate benchmark runs for your final timings.</p>' + equation('Final project target','one problem + two methods + one evidence table'))]
}

TASKS = {
2:[('Trace','Start with a = 4 and b = 9. What happens with only a = b; b = a?','Both end as 9: the first assignment loses the old a. Save it first or use a, b = b, a.'),('Calculate','Predict 17 // 5, 17 % 5 and 17 / 5 before running them.','3, 2 and 3.4; 17 = 3 × 5 + 2.'),('Change one thing','Add a 20% tax to the receipt and display two decimal places.','Use print(f"Total: {total * 1.20:.2f}"). For 4.10 × 3 the display is 14.76.')],
3:[('Trace','For the sum loop, replace range(1, 5) with range(1, 6). List each total.','1, 3, 6, 10, 15: five additions.'),('Calculate','Count body actions for two nested loops, each range(8). Compare two separate loops.','Nested: 8 × 8 = 64. Separate: 8 + 8 = 16.'),('Change one thing','Start the halving loop at 32, then 31. Predict the update counts.','32 → 16 → 8 → 4 → 2 → 1 takes 5. 31 → 15 → 7 → 3 → 1 takes 4.')],
4:[('Trace','Run the maximum logic on [−8, −3, −10]. List largest after each item.','−8, −3, −3. Starting at 0 would give a false result.'),('Calculate','How many equality checks do 20 absent-target searches need in a 10,000-item list?','20 × 10,000 = 200,000.'),('Change one thing','Change b = a to b = a.copy() in the sharing example. Predict all three lists.','a and c remain [2, 4]; b becomes [2, 4, 6].')],
5:[('Trace','Call contains([4, 7, 9], 7), then contains([4, 7, 9], 2). Count equality checks.','True after 2 checks; False after 3 checks.'),('Calculate','A batch of 100 calls takes 0.42 seconds. What is the time per call?','0.42 / 100 = 0.0042 seconds = 4.2 ms.'),('Change one thing','Move the target from absent to the first item. What changes in the experiment?','The scan now makes one equality check. This is a different input case, so record it separately.')],
6:[('Trace','Times for n = 100, 200, 400 are 2, 8, 32 ms. Compute successive ratios.','8/2 = 4 and 32/8 = 4; quadratic is a candidate model.'),('Calculate','If R = 8 for a power law, find p.','p = log₂ 8 = 3: a cubic candidate.'),('Change one thing','Add a fixed 100 ms overhead to the three example times. Recompute the ratios.','108/102 ≈ 1.059 and 132/108 ≈ 1.222. Fixed overhead hides the growing work at these sizes.')],
7:[('Trace','Draw the triangular-loop cells for n = 4. Count them.','Rows have 0, 1, 2, 3 cells: 6 total.'),('Calculate','Find the exact count for n = 100, then name its dominant term.','100 × 99 / 2 = 4,950. The dominant term is n²/2.'),('Change one thing','Replace range(i) with range(10). How does the count change?','The inner body now runs 10n times: linear instead of quadratic.')],
8:[('Trace','For T(n) = 3n + 2, verify the bound 5n at n = 1, 2 and 10.','T = 5, 8, 32; bounds = 5, 10, 50. Algebra 2 ≤ 2n proves it for all n ≥ 1.'),('Calculate','Find average equality checks for a present target uniformly placed in 9 items.','(9 + 1)/2 = 5. This depends on the stated distribution.'),('Change one thing','Change a running-sum function to return all prefix sums. What happens to result storage?','It grows from one result to n results: Θ(n) storage, assuming fixed-size numbers.')],
9:[('Trace','Write the a/b counts for aab and aba, then aab and abb.','aab/aba both have a:2, b:1 → True. abb has a:1, b:2 → False.'),('Calculate','For n = 100 and k = 26, count the two character passes plus final count checks.','100 + 100 + 26 = 226, excluding initialisation and loop overhead.'),('Change one thing','Allow uppercase letters. What must change before using the 26-slot code?','Choose case-sensitive or case-insensitive rules. For case-insensitive English input, lowercase and validate a–z before indexing; otherwise choose a larger mapping.')],
10:[('Trace','Draw each pop(0) while emptying four items. Count shifts.','3 + 2 + 1 + 0 = 6 shifts.'),('Calculate','How many shifts occur when emptying 1,000 items from the front?','1,000 × 999 / 2 = 499,500.'),('Change one thing','Replace a list queue with deque. Which operation changes, and which stays linear?','Use popleft() for O(1) front removal. Searching for an arbitrary value still costs O(n).')],
11:[('Trace','Build counts for red blue red green blue red without running code.','red:3, blue:2, green:1; one update per word.'),('Calculate','Compare 100 absent searches in 10,000 items with building a set once. Use a simple operation model.','List: 1,000,000 comparisons. Set model: about 10,000 insertions + 100 lookups, with average constant cost per operation, not an exact time ratio.'),('Change one thing','The task now asks how often each value occurs. Can the set answer it?','No: multiplicity was discarded. Use a dictionary of counts or Counter.')],
12:[('Trace','Search for 30 in [3, 7, 9, 14, 21, 28, 33, 40]. Record middle values.','14 → 28 → 33; then low = 6, high = 5, so return −1.'),('Calculate','What is the worst-case number of middle checks for 1,023 sorted items?','⌊log₂ 1023⌋ + 1 = 10.'),('Change one thing','In the range example, change the interval to [4, 4]. Predict the answer.','bisect_right(a, 4) − bisect_left(a, 4) = 3 − 1 = 2. Both copies count.')],
13:[('Trace','Draw the first bubble pass on [5, 1, 4, 2, 8]. Mark every swap.','5 swaps with 1, then 4, then 2; no swap with 8. Result [1, 4, 2, 5, 8].'),('Calculate','How many comparisons does selection sort make for n = 8?','8 × 7 / 2 = 28, even if the input is already sorted.'),('Change one thing','Reverse the order of Ada and Sam in the input. Sort by score again.','Sam now stays before Ada among the equal score-80 records. Stability preserves input order for ties.')],
14:[('Trace','Test two_sum on [4] and [4, 4] with target 8. Explain why they differ.','[4] returns False: no earlier item exists. [4, 4] returns True on the second 4, using two positions.'),('Calculate','For 1,000 items with no valid pair, compare pair tests with set lookups.','499,500 pair tests versus 1,000 set lookups plus insertions. Set operations are average O(1); the counts are not a measured speedup.'),('Change one thing','Choose one course problem for the final project. Change the input family and predict the effect before measuring.','Examples: search with early hits versus misses; sorting ordered versus reversed data; anagrams with an early mismatch versus valid pairs. Keep outputs equivalent and state the new case.')]
}


def lesson(num):
    return ''.join(section(title, body) for title, body in LESSONS[num])


def practice(num):
    return section('Three core tasks', '<p>Predict on paper, run the code, then explain any difference. Use the animations below to inspect individual steps.</p>'+''.join(task(f'{i}. {title}', prompt, answer) for i,(title,prompt,answer) in enumerate(TASKS[num],1)))
